CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261021221414_CatalogoInicial') THEN
    CREATE TABLE categorias (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Slug" character varying(60) NOT NULL,
        "Nome" character varying(100) NOT NULL,
        "Icone" character varying(120) NOT NULL,
        CONSTRAINT "PK_categorias" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261021221414_CatalogoInicial') THEN
    CREATE TABLE cursos (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Slug" character varying(120) NOT NULL,
        "NomeCompleto" character varying(200) NOT NULL,
        "NomeBreve" character varying(80) NOT NULL,
        "Descricao" text NOT NULL,
        "CategoriaId" integer NOT NULL,
        "Modalidade" character varying(20) NOT NULL,
        "CargaHorariaHoras" integer NOT NULL,
        "PublicoAlvo" character varying(300) NOT NULL,
        "Status" character varying(30) NOT NULL,
        "ImagemUrl" character varying(300) NOT NULL,
        "DataDisponibilizacao" date,
        "NomeBusca" character varying(300) NOT NULL,
        CONSTRAINT "PK_cursos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_cursos_categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES categorias ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261021221414_CatalogoInicial') THEN
    CREATE TABLE modulos (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CursoId" integer NOT NULL,
        "Ordem" integer NOT NULL,
        "Titulo" character varying(200) NOT NULL,
        CONSTRAINT "PK_modulos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_modulos_cursos_CursoId" FOREIGN KEY ("CursoId") REFERENCES cursos ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261021221414_CatalogoInicial') THEN
    CREATE TABLE aulas (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ModuloId" integer NOT NULL,
        "Ordem" integer NOT NULL,
        "Titulo" character varying(200) NOT NULL,
        "Descricao" text NOT NULL,
        CONSTRAINT "PK_aulas" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_aulas_modulos_ModuloId" FOREIGN KEY ("ModuloId") REFERENCES modulos ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

