    VALUES (1, 40, 1, NULL, 'Razão, proporção, funções e leitura de gráficos aplicadas a indicadores de produção, sensores e automação.', '/assets/imagens/hero-image.png', 'Ead', 'Matemática 4.0', 'matematica aplicada a industria 4.0 matematica 4.0', 'Matemática Aplicada à Indústria 4.0', 'Trabalhadores da indústria com ensino médio em andamento ou concluído.', 'matematica-aplicada-industria-4-0', 'InscricoesAbertas');
