    VALUES (3, 30, 2, NULL, 'Escrita clara de relatórios, e-mails e procedimentos operacionais, com foco em objetividade e revisão.', '/assets/imagens/video-thumb.png', 'Ead', 'Redação Profissional', 'comunicacao tecnica e redacao profissional redacao profissional', 'Comunicação Técnica e Redação Profissional', 'Profissionais que redigem relatórios, procedimentos ou comunicados no trabalho.', 'comunicacao-tecnica-redacao-profissional', 'InscricoesAbertas');
    INSERT INTO cursos ("Id", "CargaHorariaHoras", "CategoriaId", "DataDisponibilizacao", "Descricao", "ImagemUrl", "Modalidade", "NomeBreve", "NomeBusca", "NomeCompleto", "PublicoAlvo", "Slug", "Status")
    VALUES (4, 80, 2, NULL, 'Leitura de manuais, fichas técnicas e telas de equipamentos em inglês, com vocabulário do setor industrial.', '/assets/imagens/hero-image.png', 'Presencial', 'Inglês Instrumental', 'ingles instrumental para a industria ingles instrumental', 'Inglês Instrumental para a Indústria', 'Operadores e técnicos que lidam com manuais e equipamentos importados.', 'ingles-instrumental-industria', 'Encerrado');
    INSERT INTO cursos ("Id", "CargaHorariaHoras", "CategoriaId", "DataDisponibilizacao", "Descricao", "ImagemUrl", "Modalidade", "NomeBreve", "NomeBusca", "NomeCompleto", "PublicoAlvo", "Slug", "Status")
    VALUES (5, 48, 3, NULL, 'Propriedades de metais, polímeros e cerâmicos, e como a estrutura química define o uso de cada material.', '/assets/imagens/banner-ava.png', 'Presencial', 'Química dos Materiais', 'quimica dos materiais industriais quimica dos materiais', 'Química dos Materiais Industriais', 'Estudantes do ensino médio e técnicos interessados em processos de transformação.', 'quimica-materiais-industriais', 'InscricoesAbertas');
