DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261021221414_CatalogoInicial') THEN
    PERFORM setval(
        pg_get_serial_sequence('categorias', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM categorias) + 1,
            nextval(pg_get_serial_sequence('categorias', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('cursos', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM cursos) + 1,
            nextval(pg_get_serial_sequence('cursos', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('modulos', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM modulos) + 1,
            nextval(pg_get_serial_sequence('modulos', 'Id'))),
        false);
    PERFORM setval(
        pg_get_serial_sequence('aulas', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM aulas) + 1,
            nextval(pg_get_serial_sequence('aulas', 'Id'))),
        false);
    END IF;
END $EF$;

